import React, { useState } from "react";

const Chat = ({ personality, gender }) => {
  const [userInput, setUserInput] = useState("");
  const [chatHistory, setChatHistory] = useState([]);

  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;
  
    // 사용자의 메시지 추가
    setChatHistory((prevHistory) => [
      ...prevHistory,
      { sender: "user", message: userInput },
    ]);

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput, personality, gender }),
      });

      const data = await response.json();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: data.response },
      ]);
    } catch (error) {
      console.error("챗봇 응답 오류:", error);
    }

    setUserInput("");
  };

  return (
    <div>
      <div style={{ height: "400px", overflowY: "scroll", border: "1px solid #ccc", padding: "10px", marginBottom: "10px" }}>
        {chatHistory.map((chat, index) => (
          <div key={index} style={{ textAlign: chat.sender === "user" ? "right" : "left", margin: "5px 0" }}>
            <strong>{chat.sender === "user" ? "사용자:" : "챗봇:"}</strong> {chat.message}
          </div>
        ))}
      </div>

      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder="메시지를 입력하세요..."
          style={{ width: "300px", padding: "10px", marginRight: "10px" }}
        />
        <button onClick={handleSendMessage} style={{ padding: "10px 15px" }}>보내기</button>
      </div>
    </div>
  );
};

export default Chat;
